input.command:
git branch -a --format='%(refname:short)|%(objectname:short)|%(committerdate:relative)' | grep -v '/HEAD' | awk -F'|' '{
  if ($1 ~ /^remotes\//) {
    source = "remote"
    branch = substr($1, 9)
  } else {
    source = "local"
    branch = $1
  }
  printf "| %s | %s | %s %s |\n", branch, source, $2, $3
}' | sort

